// Song of Serenity
// status: ready
// Creatures that are enchanted can't attack or block.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); ((*so_far).is(CardType::Creature) && q.state().battlefield().iter().any(|&a| q.state().obj(a).attached_to == Some(affected) && q.chars(a).has_subtype(Subtype::Aura))) }
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, asker: &Asker, attacker: ObjectId, defender: Target) -> bool { let source = asker.source; let asker = &Asker::new(source, q.controller(source)); !((q.chars(attacker).is(CardType::Creature) && q.state().battlefield().iter().any(|&a| q.state().obj(a).attached_to == Some(attacker) && q.chars(a).has_subtype(Subtype::Aura)))) }
#[allow(unused_variables)] fn ability_0_1_rule(q: &dyn Query, source: ObjectId, blocker: ObjectId, attacker: ObjectId) -> bool { let asker = &Asker::new(source, q.controller(source)); !((q.chars(blocker).is(CardType::Creature) && q.state().battlefield().iter().any(|&a| q.state().obj(a).attached_to == Some(blocker) && q.chars(a).has_subtype(Subtype::Aura))) && true) }

